x + 2 \sqrt{2} y=1 + 8 \sqrt{2} \\ 
     \sqrt{6} x + \sqrt{2} y=\sqrt{16 \sqrt{3} + 38}
\end{cases}$ là:
\choice
{  $x=0$ và $y=4$ }
   {  $x=0$ và $y=3$ }
     { \True $x=1$ và $y=4$  }
    {  $x=1$ và $y=3$ }
\loigiai{
Từ phương trình $(1)$ rút $y = - \frac{\sqrt{2} x}{4} + \frac{\sqrt{2}}{4} + 4$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $- \frac{x}{2} + \sqrt{6} x - \sqrt{16 \sqrt{3} + 38} + \frac{1}{2} + 4 \sqrt{2} = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (1; 4)$.
}\end{ex}

\begin{ex}%[9D1V2-6]
NGhiệm của hệ phương trình $\begin{cases}
\sqrt{5} x + \sqrt{3} y=- \sqrt{12 \sqrt{15} + 47} \\ 
     \sqrt{2} x + \sqrt{6} y=- 3 \sqrt{6} - 2 \sqrt{2}
\end{cases}$ là:
\choice
{  $x=-3$ và $y=-3$ }
   {  $x=-2$ và $y=-4$ }
     {  $x=-3$ và $y=-4$ }
    { \True $x=-2$ và $y=-3$  }
\loigiai{
Từ phương trình $(1)$ rút $y = - \frac{\sqrt{15} x}{3} - \frac{\sqrt{36 \sqrt{15} + 141}}{3}$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $- \sqrt{10} x + \sqrt{2} x - \frac{\sqrt{6} \sqrt{36 \sqrt{15} + 141}}{3} + 2 \sqrt{2} + 3 \sqrt{6} = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (-2; -3)$.
}\end{ex}

\begin{ex}%[9D1V2-6]
NGhiệm của hệ phương trình $\begin{cases}
\sqrt{7} x + \sqrt{3} y=- \sqrt{4 \sqrt{21} + 31} \\ 
     2 \sqrt{2} x + 2y=- 4 \sqrt{2} - 2
\end{cases}$ là:
\choice
{  $x=-3$ và $y=-1$ }
   { \True $x=-2$ và $y=-1$  }
     {  $x=-2$ và $y=-2$ }
    {  $x=-3$ và $y=-2$ }
\loigiai{
Từ phương trình $(1)$ rút $y = - \frac{\sqrt{21} x}{3} - \frac{\sqrt{12 \sqrt{21} + 93}}{3}$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $- \frac{2 \sqrt{21} x}{3} + 2 \sqrt{2} x - \frac{2 \sqrt{12 \sqrt{21} + 93}}{3} + 2 + 4 \sqrt{2} = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (-2; -1)$.
}\end{ex}

\begin{ex}%[9D1V2-6]
NGhiệm của hệ phương trình $\begin{cases}
3 x + 2y=-10 \\ 
     2 x + \sqrt{6} y=- 2 \sqrt{6} - 4
\end{cases}$ là:
\choice
{  $x=-3$ và $y=-3$ }
   { \True $x=-2$ và $y=-2$  }
     {  $x=-3$ và $y=-2$ }
    {  $x=-2$ và $y=-3$ }
\loigiai{
Từ phương trình $(1)$ rút $y = - \frac{3 x}{2} - 5$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $- \frac{3 \sqrt{6} x}{2} + 2 x - 3 \sqrt{6} + 4 = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (-2; -2)$.
}\end{ex}

\begin{ex}%[9D1V2-6]
NGhiệm của hệ phương trình $\begin{cases}
\sqrt{5} x + \sqrt{2} y=\sqrt{6 \sqrt{10} + 23} \\ 
     \sqrt{2} x + 2 \sqrt{2} y=7 \sqrt{2}
\end{cases}$ là:
\choice
{  $x=0$ và $y=3$ }
   {  $x=1$ và $y=2$ }
     {  $x=0$ và $y=2$ }
    { \True $x=1$ và $y=3$  }
\loigiai{
Từ phương trình $(1)$ rút $y = - \frac{\sqrt{10} x}{2} + \frac{\sqrt{12 \sqrt{10} + 46}}{2}$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $- 2 \sqrt{5} x + \sqrt{2} x - 7 \sqrt{2} + \sqrt{2} \sqrt{12 \sqrt{10} + 46} = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (1; 3)$.
}\end{ex}

\begin{ex}%[9D1V2-6]
NGhiệm của hệ phương trình $\begin{cases}
\sqrt{7} x + 2 \sqrt{2} y=- 3 \sqrt{7} + 8 \sqrt{2} \\ 
     \sqrt{3} x + \sqrt{3} y=\sqrt{3}
\end{cases}$ là:
\choice
{ \True $x=-3$ và $y=4$  }
   {  $x=-4$ và $y=3$ }
     {  $x=-4$ và $y=4$ }
    {  $x=-3$ và $y=3$ }
\loigiai{
Từ phương trình $(1)$ rút $y = - \frac{\sqrt{14} x}{4} - \frac{3 \sqrt{14}}{4} + 4$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $- \frac{\sqrt{42} x}{4} + \sqrt{3} x - \frac{3 \sqrt{42}}{4} + 3 \sqrt{3} = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (-3; 4)$.
}\end{ex}
